window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-08T10:33:23.568Z","stories":{"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic 拟感恩节前 IPO，估值预期下调至 1.25–1.75 万亿美元","status":"active","sourceCount":20,"reportCount":61,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-08T00:44:04.537Z","latest":"消息称 Anthropic 仍推进 IPO：拟募资 800 亿至 1000 亿美元，估值预期回落","digest":"Anthropic 仍在推进感恩节前上市，拟募资 800–1000 亿美元，目标估值 1.25 万亿–1.75 万亿美元。据《金融时报》援引投资者消息，CEO 阿莫迪已接受低于此前预期的估值水平；公司 9 月曾瞄准最高 2 万亿美元。\n\n估值下调发生在投资者质疑之后。据 Reuters 和 WSJ，投资者认为 1.5 万亿美元过高，有人提出仅 1 万亿美元，并怀疑原定下周启动的路演能否如期进行，还在等待更新文件未包含的 10 月营收数据。\n\n公司此前公开提交 S-1，拟在纳斯达克以代码 ANT 发行 A 类股，由高盛和摩根士丹利承销。更新后的 S-1/A 首次披露第三季度业绩：经营利润从二季度盈利 9.74 亿美元转为亏损 5.67 亿美元，Q3 营收 170 亿美元，算力成本占营收比例从 48% 升至 58%；算力与基础设施合同承诺约 8954 亿美元，另有最高 1750 亿美元尚未定价。上市后，长期受益信托可任命七名董事中的四席，七位联合创始人合计掌握 50.1% 投票权。","digestUpdatedAt":"2026-11-08T01:19:04.500Z","reports":[{"id":"cjulee90gasnt7mbhmxcuiiqj","title":"消息称 Anthropic 仍推进 IPO：拟募资 800 亿至 1000 亿美元，估值预期回落","summary":"据《金融时报》报道，Anthropic 仍在推进感恩节前的 IPO，预计募资 800 亿至 1000 亿美元，目标估值 1.25 万亿至 1.75 万亿美元，CEO 阿莫迪接受估值低于此前投资者预期的水平。科技股抛售和美国中期选举结果使上市难度上升，OpenAI 也已将私募估值从 1.4 万亿美元下调至 1.25 万亿美元。七位联合创始人已承诺将个人所持股权的 80% 捐给慈善事业。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-08T00:44:04.537Z","url":"https://www.ithome.com/1/023/854.htm"},{"id":"okhx4jjwucd647299qwzsl6ua","title":"Anthropic 拟感恩节前 IPO，接受低于预期的估值，募资 800–1000 亿美元","summary":"据《金融时报》援引投资者的消息，Anthropic 计划在感恩节前 IPO，拟募资 800–1000 亿美元，估值 1.25–1.75 万亿美元，低于最乐观投资者期望的 2 万亿美元，但高于当前 9650 亿美元。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T17:37:25.000Z","url":"https://the-decoder.com/anthropic-pushes-ahead-with-pre-thanksgiving-ipo-despite-tech-selloff-accepts-lower-valuation/"},{"id":"losfqwxesuanjnt62v032oo9o","title":"Anthropic IPO 估值存分歧，1.5 万亿美元仍被部分投资者嫌贵","summary":"据路透社报道，Anthropic 冲刺史上最大 IPO 时估值预期持续下调，原拟寻求高达 2 万亿美元估值，部分机构投资者认为 11 月上市时应在 1.5 万亿至 1.6 万亿美元之间，甚至有大型投资者认为更接近 1 万亿美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T01:36:48.637Z","url":"https://www.ithome.com/1/023/640.htm"},{"id":"kv9zqeiqr9wj29j6vmq9q6je6","title":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","summary":"据 WSJ，投资者已将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T，部分人认为 $1T 更现实。民主党中期选举获胜后数据中心禁令担忧引发 $3.2T 美股抛售；Anthropic 10 月底 run rate 仍超 $80B，9 月 30 日持有 $146.6B 现金。OpenAI 在 $1.25T 估值下仅募得 $30B 目标中的 $11B，同样反映融资走弱。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T14:56:34.000Z","url":"https://x.com/rohanpaul_ai/status/2118719195072659833"},{"id":"ia9wi0z09zfes5ewdf4agb6nf","title":"Anthropic 1.5 万亿美元 IPO 因投资者质疑估值遇阻","summary":"据 Reuters，Anthropic 的 IPO 遇阻，投资者质疑 1.5 万亿美元估值过高，有投资者提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:38:17.000Z","url":"https://the-decoder.com/anthropics-1-5-trillion-ipo-hits-resistance-as-investors-balk-at-valuation/"},{"id":"zzv4fx8jpa3068v4y2wxsw2ey","title":"Newcomer：OpenAI 与 Anthropic 融资路径分化，Anthropic IPO 仍在推进","summary":"Newcomer 作者采访参与两家融资的投资人后写道，Anthropic 正与 OpenAI 拉开距离，而 OpenAI 渴望翻身故事。有投资人称共同基金等长期投资者对 Anthropic 股份需求无限，预计 IPO 将在感恩节前完成；民主党中期选举大胜后政治环境更严峻，但 Anthropic 与民主党关系相对友好。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-04T21:15:13.000Z","url":"https://www.newcomer.co/p/latest-fundraising-efforts-show-openai"},{"id":"mr034xi1abyzx7gazv7l248lg","title":"Anthropic 明年 700 亿美元算力账单超全年收入，S-1 细节遭播客拆解","summary":"Saito 在听完 Prof G Markets 播客后撰文分析 Anthropic S-1 修订稿，指出其未来几年算力与数据中心总承诺达 8950 亿美元，其中未来 12 个月到期 700 亿美元，超过其 680 亿美元的年化收入（上季度收入 170 亿美元，同比涨 12 倍但环比增速从 144% 降至 47%）。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-04T09:37:20.000Z","url":"https://x.com/SaitoWu/status/2117914080371782063"},{"id":"zv5dl1agqwo6tkmhdamy17lt5","title":"Ed Zitron 解析 OpenAI 1.25 万亿美元估值融资与 Anthropic S-1/A 中的万亿级算力承诺","summary":"Ed Zitron 撰文认为 AI 行业资金正在枯竭。OpenAI 上周以 1.25 万亿美元估值融资 110 亿美元，低于此前计划的 300 亿美元、1.4 万亿美元估值；据 The Information，其 Q1 2026 成本收入与研发支出合计 121 亿美元，截至 3 月底持有逾 730 亿美元现金及有价证券。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:16:20.000Z","url":"https://www.wheresyoured.at/running-dry/"},{"id":"byq9z2oinyhjrd8hrxql51wg5","title":"Anthropic S-1 新披露显示算力成本占比升至 58%，利润率承压","summary":"TechCrunch 分析 Anthropic 更新的 S-1 文件披露，Q3 营收达 170 亿美元、环比增长近 50%，但算力占营收比例从上一季的 48% 升至 58%，每美元算力对应营收从峰值约 2.08x 回落至 1.72x。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:07:01.000Z","url":"https://techcrunch.com/2026/11/03/anthropic-is-still-grappling-with-the-economics-of-compute/"},{"id":"fey67gtp70ulqn8j5il7kycxg","title":"Anthropic 在 S-1/A 招股文件中警示递归自我改进（RSI）临近","summary":"Anthropic 在周一更新的 S-1/A 招股补充文件风险提示中称，公司已利用 AI 开发新模型且部分能力跃升未被及时察觉，基于对下一代模型的内部预期，可能很快触及《负责任扩缩策略》定义的“由 AI 带来的爆发式技术进展”，即递归自我改进（RSI）标准。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-03T08:03:19.683Z","url":"https://www.ithome.com/1/021/626.htm"},{"id":"dertdpzq3sm7jhkbxyfqwxspp","title":"Anthropic 修订版 IPO 文件披露 8954 亿美元算力承诺，总额可达 1.07 万亿美元","summary":"Anthropic 在修订版 IPO 文件中披露 8954 亿美元算力承诺，另有最高 1750 亿美元合同尚未定价，总额约 1.07 万亿美元，约为其前九个月 332 亿美元收入的 32 倍。款项持续到 2045 年，一年内到期 698 亿美元，而公司现金及短期投资为 1319 亿美元；季度环比增速从 144% 放缓至 47%，收入达 170 亿美元，算力成本升至销售额的 58%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-03T00:03:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117407218849157258"},{"id":"h052dra38w9bfsy0ne6frvfpv","title":"GPU 租金半年翻倍，Tomasz Tunguz 解析 2027 年 AI 实验室的久期匹配难题","summary":"Tomasz Tunguz 基于 Anthropic S-1/A 数据分析称，GPU 短租价格从 $3 涨到 $12-13/小时，使 Anthropic 混合 GPU 等效小时成本从 $3.10 升至 $5.65。","sourceName":"Tomasz Tunguz 博客（VC 分析）","firstParty":false,"publishedAt":"2026-11-03T00:00:00.000Z","url":"https://tomtunguz.com/the-financial-engineering-essential-for-ai-in-2027/"},{"id":"p61czu93us1j0lli5em6rjkte","title":"WSJ：大投资者希望 Anthropic IPO 估值定在 1.5 万亿至 1.6 万亿美元","summary":"据 WSJ，大投资者希望 Anthropic 的 IPO 估值定在 1.5 万亿至 1.6 万美元区间，低于数月来讨论的近 2 万亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T23:40:43.000Z","url":"https://x.com/rohanpaul_ai/status/2117401551526600969"},{"id":"uj1dp8gyin78j1xfse943y5w0","title":"Anthropic 在 S-1A 中披露可能很快达到自身 RSI 定义","summary":"TechCrunch 报道，Anthropic 在周一修订的 S-1A 文件风险因素部分新增表述，称内部估计显示其可能很快达到负责任扩展政策中「AI 带来的显著加速进展」的定义，且过去曾未察觉 AI 研发带来的能力跃升，但目前没有任何现有模型被认定越过该阈值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-02T22:14:50.000Z","url":"https://techcrunch.com/2026/11/02/anthropic-warns-that-its-very-close-to-rsi-capability-aka-self-building-ai/"},{"id":"xiu342i7osbgfxe2ezhrjndl0","title":"Anthropic 算力与基础设施合同承诺达 $895.4B，其中 $447.5B 须在 2031 年前支付","summary":"Anthropic 在更新的 IPO 文件中首次披露第三季度业绩，算力与基础设施合同承诺总额约 $895.4B，其中 $447.5B 须在 2031 年前支付，仅 $213.8B 可取消或附带条件。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T21:28:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117368258571784296"},{"id":"p2ckhch6idwqa3tpmqqp2inb8","title":"Anthropic 更新的 S1/IPO 文件称未来模型可能临近递归自我改进阈值","summary":"Anthropic 更新的 S1/IPO 申报文件显示未来模型可能很快达到其递归自我改进（RSI）阈值，即 AI 能力以无重大 AI 帮助时最快持续速度的 2 倍提升，1 年相当于 2 年进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T18:43:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117326734442049563"},{"id":"xvemmg9p83lxqktk7mc47zhcr","title":"Anthropic 更新 IPO 文件首次披露第三季度财报，从盈利 9.74 亿美元转为亏损 5.67 亿美元","summary":"Anthropic 更新 S-1 IPO 文件并首次披露第三季度业绩，经营利润从二季度盈利 9.74 亿美元转为三季度亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T16:01:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117285920500273582"},{"id":"dpm21l66z2iizblehsdg09c8t","title":"美国白宫科技顾问萨克斯称 Anthropic 可能成为资本主义史上最伟大企业","summary":"美国白宫科学与技术顾问会议主席戴维·萨克斯在 All-In 播客分析 Anthropic 的 S-1 文件，称其很可能成为资本主义历史上最伟大企业，也可能是回报最高的风险投资项目。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T22:56:28.467Z","url":"https://www.ithome.com/1/020/633.htm"},{"id":"yqblvh40gus1ssc0rjvawh6fu","title":"Anthropic IPO 招股文件披露近 9000 亿美元隐性债务","summary":"Anthropic 近日提交 IPO 招股文件，彭博社报道其计划未来在服务器、建筑和电力等领域投入近 9,000 亿美元债务。该公司资产负债表显示 1,175 亿美元负债和 1,120 亿美元现金，而租赁合同及数据中心、电力和 GPU 采购协议等表外义务未直接体现；Anthropic 计划通过增加收入和筹集资金支付这些负债。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T03:25:09.697Z","url":"https://www.ithome.com/1/020/444.htm"},{"id":"vyd3tzicoe478uo8njsr8zt2v","title":"The Verge 解读 Anthropic S-1 文件中的奇迹叙事与风险披露","summary":"The Verge 分析 Anthropic 提交的 335 页 S-1 招股书，其中创始人信以带来奇迹时代为愿景，同时用 94 页风险因素警告模型可能对人类构成灾难性甚至生存风险。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T13:11:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1023070/anthropic-ipo-risk-factors-filing-miracles"},{"id":"ix29bodadp5bou498z79oflc2","title":"Anthropic S-1 披露：三分之二以上算力用于研发，服务客户仅占约四分之一","summary":"Rohan Paul 引用 Anthropic S-1 指出，至少三分之二的芯片开支用于模型训练、研发和 Claude 内部使用，而非服务客户。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-30T01:28:37.000Z","url":"https://x.com/rohanpaul_ai/status/2115979152100864127"},{"id":"wb6emxuh5ob2wh96egtwawgfu","title":"Anthropic S-1 文件解读：财务表现强劲但增长放缓存隐忧","summary":"作者通读 Anthropic 公开版 S-1 文件，认为公司财务状况好于预期：2026 年第二季度收入从一季度的 47 亿美元增至 116 亿美元，并录得首个运营利润，截至 6 月底现金储备仅次于 Google 和 Berkshire Hathaway。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T19:10:41.000Z","url":"https://www.understandingai.org/p/anthropics-financials-are-surprisingly"},{"id":"o37r0y04qmlpx7m674ztwgsjr","title":"Anthropic 披露约 250 个客户年消费超 1000 万美元","summary":"Anthropic 在 Form S-1 注册文件中披露，截至 2026 年 9 月 30 日的 12 个月内，约 250 个客户对 Claude 的支出超过 1000 万美元。Fortune 10 全部企业每年支付至少 10 万美元，超过 50% 的 Fortune 500 和超过 30% 的 Global 2000 亦是如此；年付 10 万美元以上的客户贡献 2025 年收入的 76%，低于 2023 年的 90%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T17:19:28.000Z","url":"https://x.com/rohanpaul_ai/status/2115856053015580896"},{"id":"r9bmkfh02wkycc8zmhw87h4q9","title":"SemiAnalysis 分析师解读 Anthropic S-1 招股书背后的 AI 经济账","summary":"The Verge Decoder 节目邀请 SemiAnalysis 分析师 Joey Brookhart 解读 Anthropic 提交的 S-1 招股书，公司拟在纳斯达克上市，估值区间 1.5 万亿至 2 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T14:00:00.000Z","url":"https://www.theverge.com/podcast/1021322/anthropic-ipo-filing-s-1-claude-semianalysis-joey-brookhart-interview"},{"id":"iuma7p8unle567lzy6hp5jpw9","title":"The Verge 解读 Anthropic S-1：约 8500 亿美元 compute 承诺押注递归自我改进","summary":"The Verge 作者分析 Anthropic S-1，认为其商业模式依赖高速增长：2026 上半年营收同比增长 14 倍至 $16.3 billion，净收入留存率 900%，但不可撤销采购承诺合计 $265.6 billion，加上未开始的租赁协议 $321.4 billion 及其他协议，未来 20 年承诺至少约 $850 billion。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:30:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1021476/anthropic-s-1-compute-recursive"},{"id":"x2h1bp5shee6v508nw7pjtvas","title":"Ed Zitron 长文解析 Anthropic S-1：称其把散户当作退出流动性","summary":"Ed Zitron 撰文批评 Anthropic 的 S-1 招股书，指其仅披露 Q2 盈利数据、省略 Q3 现金状况和付款明细，是在公司基本面变化前误导投资者。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-10-28T17:51:00.000Z","url":"https://www.wheresyoured.at/exit-liquidity/"},{"id":"vidjbhx5bf45wdl488kst1wv8","title":"Anthropic IPO 文件披露现金及短期投资达 131.7B 美元，超过 Amazon 和 Microsoft","summary":"Anthropic 的 IPO 文件显示其现金及短期投资达 $131.7B，超过 Amazon 和 Microsoft，在美国非银行公司中仅次于 Berkshire Hathaway 和 Alphabet。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T17:11:27.000Z","url":"https://x.com/rohanpaul_ai/status/2115491649543635378"},{"id":"x1rs553t7mu2o69tdy90e54nc","title":"TechCrunch 解析 Anthropic IPO 治理结构：公众股东对董事会几乎没有话语权","summary":"TechCrunch 发文分析 Anthropic IPO 后的治理结构，公众股东对董事会人选几乎没有话语权。Long-Term Benefit Trust（成员包括 Ben Bernanke）持有 Class T 股，可选举和罢免 7 个董事席位中的多数；7 位联合创始人合计掌握 50.1% 股东投票权和 3 个董事会席位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T15:27:21.000Z","url":"https://x.com/rohanpaul_ai/status/2115465450469601487"},{"id":"gxwqce1swocfo9bp3dgqy3dnj","title":"Anthropic S-1 显示 90% 增量毛利，SemiAnalysis 播客详解其中数字","summary":"Saito 转述 SemiAnalysis 播客对 Anthropic S-1 的解读：招股书口径为增量毛利 90%、推理毛利 85%、连续两个季度盈利，Q1 净收入留存达 500%，收入同比涨 1368% 而算力费用只涨 300%。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-10-28T09:32:56.000Z","url":"https://x.com/SaitoWu/status/2115376256929948006"},{"id":"c5zdgpchio31r2911elz4bbg6","title":"Anthropic 上市文件披露四类芯片混用布局，分析师称英伟达定价权或承压","summary":"据《商业内幕》10 月 28 日报道，Anthropic 在 S-1 上市申请文件中披露，公司把多家战略合作伙伴的算力整合成统一资源池，通过软件将计算任务分配到亚马逊 Trainium、谷歌 TPU、英伟达 GPU 和 AMD GPU 四类芯片上，以分散风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-28T06:35:47.357Z","url":"https://www.ithome.com/1/018/906.htm"},{"id":"q287d5f1xom92gova9cmmlq5g","title":"Anthropic IPO 文件将潜在市场规模估为每年 40 万亿美元","summary":"据 WSJ 报道，Anthropic 在 IPO 文件中将潜在市场规模估为每年 40 万亿美元，超过 SpaceX 此前 28.5 万亿美元的估算。其做法是把 2025 年全球知识工作者创造的经济价值（超过 40 万亿美元）整体视为自身市场，理由是前沿 AI 能提升这些工作者的生产力从而扩大该价值。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T02:05:34.000Z","url":"https://x.com/rohanpaul_ai/status/2115263675124838643"},{"id":"b61d349yqp5mt029fsa0ytbv9","title":"Anthropic IPO 最大赢家或为 Amazon 而非 VC","summary":"TechCrunch 根据 Anthropic 的 S-1 分析，VC 持股均不足 5%，而 Amazon 可能是 IPO 最大财务受益方。Amazon 持有 62 亿美元本金可转债、其自估持仓价值 979 亿美元，另投 100 亿美元无投票权优先股，累计投资约 180 亿美元；Anthropic 还承诺未来 10 年在 AWS 至少消费 1100 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-28T01:15:28.000Z","url":"https://techcrunch.com/2026/10/27/vcs-will-make-billions-on-anthropics-ipo-but-amazon-is-set-to-make-much-much-more/"},{"id":"lre38a418cjju32u8z01oxq7p","title":"Anthropic IPO 后的治理结构解析：LTBT 与创始人如何掌握控制权","summary":"TechCrunch 解析 Anthropic 上市后的公司治理结构，普通股股东对董事会组成等重大决策几乎没有话语权。Long Term Benefit Trust 持有特殊股票，可任免 4 个 Class T 董事席位中的多数，成员包括 Ben Bernanke 等；七位创始人以 50.1% 投票权选举 3 名董事。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:38:28.000Z","url":"https://techcrunch.com/2026/10/27/whos-really-in-charge-at-anthropic-after-the-ipo/"},{"id":"p0qsqyotghrfc85w9omv8w3no","title":"Anthropic IPO 招股书警示其 AI 可能勒索人类、产生意识甚至终结人类","summary":"SEC 周一公布 Anthropic 的 S-1 招股书，其中 93 页、超 7 万字的风险因素部分除常规经营风险外，还披露其 AI 可能勒索用户、产生意识乃至威胁人类等特殊风险。Ars Technica 作者通读全文后筛选出七条最令人意外的潜在问题，供潜在投资者参考。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:31:14.000Z","url":"https://arstechnica.com/ai/2026/10/anthropic-ipo-warns-its-ai-could-blackmail-people-become-sentient-end-humanity/"},{"id":"xhwtx8zwvvmyou5emtd3dbzbn","title":"Azeem Azhar 图解 Anthropic S-1 财务数据","summary":"Azeem Azhar 图解 Anthropic 的 S-1 文件，指出公司已从实验室变成有现金流和资金的业务，看起来能走向可靠盈利。增长仍高但放缓，超过 80% 的营收来自发布不到六个月的模型；Q3 因向基金会付款可能出现边际亏损，客户集中度问题不大。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-10-27T17:31:56.000Z","url":"https://www.exponentialview.co/p/anthropics-s-1-in-charts"},{"id":"x9a9nhbuq2ncarw5i41jhryjc","title":"Anthropic 拟以特殊治理结构抵御 IPO 后股东的安全施压","summary":"Anthropic 计划通过长期受益信托和 Founder LLC 等独特治理结构上市，在公开市场融资的同时防止股东迫使公司削弱安全投入。信托的五名投票受托人可通过 Class T 股票任命七名董事中的四席，七位创始人则以 Founder LLC 掌握 50.1% 投票权。法学专家认为法律层面可隔绝逐利压力，但市场竞争、融资需求和创始人离开都可能侵蚀这些保障。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T16:51:22.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1019470/anthropic-ipo-resist-investor-pressure-cut-corners-safety"},{"id":"p24kw8c06nmy1hzs3spvr4aha","title":"Every 解读 Anthropic S-1：上线超过六个月的模型贡献收入不足 20%","summary":"Every 的 Context Window 通讯解读 Anthropic 周一提交的上市 S-1 文件，指出其重度依赖最新模型，发布超过六个月的模型收入占比不足 20%。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-10-27T16:00:00.000Z","url":"https://every.to/context-window/every-model-has-a-six-month-shelf-life-now"},{"id":"kcf7zccr5zy620rfc3d7ufsbe","title":"Anthropic 在 S-1 文件中重申永远不会在 Claude 对话中展示广告","summary":"Anthropic 向美国证券交易委员会提交 S-1 文件，计划以“ANT”为股票代码在纳斯达克 IPO，并在文件中重申永远不会在 Claude 对话中展示广告。公司表示一旦广告成为收入目标，优化用户参与度的压力会随之增加，因此不让这种压力进入 Claude；此前 Anthropic 曾批评 OpenAI 在 ChatGPT 中投放广告，警告其可能比传统广告更具操纵性。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T11:37:54.953Z","url":"https://www.ithome.com/1/018/641.htm"},{"id":"mnd8e4p8qhc4gwhlz5drvjmmr","title":"Anthropic 在 IPO 信中重申 Claude 永不投放广告","summary":"Anthropic 在 IPO 申请的附信中再次承诺 Claude 聊天界面不会出现广告，称一旦广告成为营收目标，优化参与度的压力就会增长，公司选择不引入这种压力。信中还以安全考量延迟发布 Claude Fable 5、并向网络防御者提供约 1 亿美元免费 Claude 额度为例，说明公司把价值观置于利润之上。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-27T11:20:51.000Z","url":"https://the-decoder.com/anthropic-uses-its-ipo-letter-to-renew-its-pledge-that-claude-will-never-show-ads/"},{"id":"nbvleghbxraalsahhggnc6qov","title":"Latent Space 解读 Anthropic 提交 S-1：拟以代码 AN 上市纳斯达克，H1 2026 营收 16.3B 美元","summary":"Latent Space 汇总解读 Anthropic 公开提交的 S-1 文件，公司计划以代码 AN 上市纳斯达克，营收从 2023 年的 41M 美元增至 H1 2026 的 16.3B 美元，Q2 营收 11.6B 美元同比增长 1,368%，营业利润 974M 美元，H1 2026 毛利率达 85%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-10-27T07:24:59.000Z","url":"https://latent.space/p/ainews-anthropic-s1/"},{"id":"rc69ll5k6qnwpfqckkb1x8wmr","title":"Anthropic S-1 上市文件披露 AI 产业严重依赖天然气","summary":"据 The Verge 报道，准备上市的 Anthropic 在 S-1 注册文件中承认，生成式 AI 数据中心越来越依赖以甲烷为主要成分的天然气，供电和选址面临激烈竞争。文件将气候变化视为经营风险，指燃料涨价、燃气轮机供应不足和监管限制可能制约其数据中心建设，公司此前宣布了 500 亿美元投资计划，用于扩大得克萨斯州和纽约州的数据中心规模。天然气发电目前占美国发电总量的 40%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T03:09:14.067Z","url":"https://www.ithome.com/1/018/270.htm"},{"id":"t6evqsenxfytsi8wl7h1urjxr","title":"Anthropic 招股书拆解：IPO 计划募资约 1000 亿美元背后的 11 个细节","summary":"作者总结 Anthropic IPO 招股书的 11 个细节，计划募资约 1000 亿美元、估值或达 1.5万亿～2万亿。收入五个季度涨 30 倍，今年二季度经营利润首次转正 9.74 亿美元，但上半年净亏 807 亿美元，主要来自可转换票据公允价值变动；调整后净利润为正 26.71 亿美元。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-10-27T00:34:38.000Z","url":"https://x.com/Khazix0918/status/2114878401190506902"},{"id":"yl0873sjcoprds9zoi03gv3dl","title":"Anthropic 向 SEC 递交 S-1 招股书，代码「ANT」，披露 2026 上半年营收 162.86 亿美元","summary":"Anthropic 向 SEC 公开递交 S-1 招股书，代码「ANT」，由高盛和摩根士丹利承销。2026 上半年营收 162.86 亿美元，同比增长约 1300%，经营亏损从 21.35 亿收窄至 6.93 亿美元，Q2 已实现约 9.74 亿美元 GAAP 经营利润；净亏损 807.48 亿美元，其中约 723.88 亿为与估值上升相关的非现金会计损失。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-10-27T00:05:08.000Z","url":"https://x.com/indigox/status/2114870981034725662"},{"id":"dw9465ajr0oz1vf6ricf2074f","title":"Anthropic IPO 招股书11个细节解读：千亿募资、807亿美元亏损与7美元控股权","summary":"作者梳理了 Anthropic 提交的 IPO 招股书中的11个细节。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-10-27T00:05:00.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA%3D%3D&mid=2647687831&idx=1&sn=6502cb593318d6e324e29d278fae4fcc"},{"id":"jb1oibqp1rw1ltmm9k7cg7b7q","title":"Anthropic 在 IPO 文件中披露公司内部也存在对先进 AI 灾难性风险的担忧","summary":"Anthropic 在 IPO 文件中告知投资者，公司内部和其他研究者、监管者都担忧足够先进的 AI 系统若缺乏妥善防护，可能给人类带来灾难性或生存性风险。文件同时警告 1300% 的增速不可持续、无法保证营收继续增长，且保险业可能没有足够能力承保此类风险。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-26T23:20:52.000Z","url":"https://x.com/rohanpaul_ai/status/2114859840204165363"},{"id":"qkdi24ffzg442oh8tv0bc9zsw","title":"Anthropic S-1 文件显示上半年营收 $16.3B、净亏损 $80.7B 主要来自固定价购股权","summary":"Anthropic 向 SEC 提交 S-1 文件，上半年六个月营收 $16.3B，是去年同期的 14 倍，经营亏损收窄至 $693M。$80.7B 净亏损中约 $72.4B 加 $9.4B 来自 Amazon 和 Google 以 $259 固定价购股、可转债价值上涨产生的账面损失，没有现金流出，业务实际亏损仅约 $0.7B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-26T22:55:14.000Z","url":"https://x.com/rohanpaul_ai/status/2114853388664115421"},{"id":"sdlw6fmaxnodj24clpcb505gl","title":"Anthropic S-1 文件披露数据中心依赖天然气并面临能源成本风险","summary":"The Verge 报道，Anthropic 在向美国 SEC 提交的 S-1 文件中承认，其数据中心日益依赖天然气发电，部分规划中的数据中心使用现场燃气轮机供电，燃料成本上升和供应链限制可能威胁其扩张。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-26T21:45:31.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1018994/anthropic-ipo-ai-data-center-energy-climate-risk"},{"id":"jt9flkwupl81g1p7hy80phck3","title":"Anthropic 提交 IPO 招股书，披露 163 亿美元半年营收与约 7800 亿美元算力承诺","summary":"Anthropic 向 SEC 公开提交 S-1 招股书，计划以代码 ANT 登陆纳斯达克，由 Goldman Sachs 和 Morgan Stanley 牵头，Wall Street 预期估值约 2 万亿美元，高于此前约 9650 亿美元的私人估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-26T19:14:45.000Z","url":"https://the-decoder.com/anthropic-opens-its-books-for-wall-street-showing-record-revenue-and-mounting-obligations/"},{"id":"y1ot4d0c671m0aveshrvsc1h2","title":"Gary Marcus 指出 Anthropic 草拟 S-1 中缺失了 Q3 数据","summary":"Gary Marcus 评点 Anthropic 当日发布的草拟 S-1，指出其中部分地方直接缺失了 Q3 数据。他此前提醒关注 S-1 中对近几个月需求变化的披露，认为这与 tokenmaxxing 退潮、低成本替代模型走热有关，并以福尔摩斯“夜里狗没有叫”的典故暗示缺席本身值得注意。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-10-26T17:57:52.000Z","url":"https://garymarcus.substack.com/p/what-anthropic-left-out-of-their"},{"id":"yhz6w8o0n8dbz2if6d2djzim2","title":"Anthropic S-1 文件关键数据与要点整理","summary":"Newcomer 梳理 Anthropic 递交的 S-1 文件中的关键数据与细节，面向风险投资人整理要点。文章指出该文件发布于科技行业敏感时刻，全美反 AI 情绪高涨且临近一场影响重大的选举，这些数字可能进一步加剧相关争论。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-10-26T17:44:56.000Z","url":"https://www.newcomer.co/p/anthropics-s-1-key-data-points-and"}]},"a983842e-37eb-436c-9026-711d2fa63657":{"publicId":"a983842e-37eb-436c-9026-711d2fa63657","title":"Anthropic 发布研究拆解 Claude 智能体记忆机制","status":"active","sourceCount":3,"reportCount":3,"firstReportAt":"2026-11-05T16:00:00.000Z","latestAt":"2026-11-06T23:25:14.860Z","latest":"Anthropic 研究《The components of agent memory》：Claude 智能体靠做梦机制整理记忆提升长任务表现","digest":"Anthropic 发布研究文章《The components of agent memory》，拆解 Claude 智能体的跨会话记忆机制：会话中写记忆笔记、判断信息显著性，并在空闲时段以“dreaming”回顾日志、纠正错误、构建知识结构，以便下次更快找到所需信息。Anthropic 称，dreaming 帮助 Claude 整理学到的内容、纠正错误并提升检索便利性。\n\n上述机制与效果均出自 Anthropic 自己的研究文章和工程博客，尚无第三方验证。","digestUpdatedAt":"2026-11-06T23:38:58.631Z","reports":[{"id":"dlzqgg5x8fwm7lykc2516792t","title":"Anthropic 研究《The components of agent memory》：Claude 智能体靠做梦机制整理记忆提升长任务表现","summary":"Anthropic 于 11 月 6 日发布研究文章《The components of agent memory》，拆解 Claude 智能体的跨会话记忆机制，提出借鉴人脑睡眠整理记忆的方式，在空闲时段回顾日志、纠错并构建知识结构。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-06T23:25:14.860Z","url":"https://www.ithome.com/1/023/613.htm"},{"id":"wf9vzojwrda427znntwp2s0r8","title":"Anthropic 工程博客解析 Claude“做梦”如何整理智能体记忆","summary":"Anthropic 发布工程博客文章，介绍记忆如何让 Claude 从经验中学习，以及“dreaming”如何帮助 Claude 整理学到的内容、纠正错误、并在下次更方便地找到所需信息。文章链接：https://www.anthropic.com/research/components-of-agent-memory","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-06T21:16:17.000Z","url":"https://x.com/AnthropicAI/status/2118814753154064501"},{"id":"d28mrqwr7h7tl8b8jcse4b449","title":"Anthropic 拆解 Claude 智能体记忆的组成：笔记、显著性判断与 dreaming","summary":"Anthropic 发布研究文章，介绍其设计 Claude 智能体记忆的思路与多组评测，包括会话内写记忆笔记、离线 dreaming 整理记忆和 wiki 表示。","sourceName":"Anthropic：Research（发表成果 · 网页）","firstParty":true,"publishedAt":"2026-11-05T16:00:00.000Z","url":"https://www.anthropic.com/research/components-of-agent-memory"}]},"fba07069-fd3e-44bd-ad2d-f347f820dab3":{"publicId":"fba07069-fd3e-44bd-ad2d-f347f820dab3","title":"OpenAI 110亿美元首笔融资到账，估值1.25万亿","status":"active","sourceCount":4,"reportCount":4,"firstReportAt":"2026-11-06T21:10:13.000Z","latestAt":"2026-11-07T09:45:23.000Z","latest":"OpenAI 获得 110 亿美元融资首笔，估值 1.25 万亿美元","digest":"据 Bloomberg 援引知情人士报道，OpenAI 新一轮融资的首笔约 110 亿美元已由投资者打款，投后估值 1.25 万亿美元。TechCrunch 称，这轮融资尚未关闭，预计数周内完成，总额可能约 200 亿美元。\n\nThe Decoder 称，OpenAI 原计划以 1.4 万亿美元估值融资 300 亿美元，因 AI 板块抛售而缩水；投资方包括 Coatue、SoftBank、红杉、a16z 等，另在通过投行引入富裕个人投资者。The Verge 提到，OpenAI 今年 3 月曾以 8520 亿美元估值融资 1220 亿美元。本轮最终募资总额和估值仍取决于能否按预期完成。","digestUpdatedAt":"2026-11-07T10:46:36.205Z","reports":[{"id":"dylhmpqmmpf0ep3ccil29t1uv","title":"OpenAI 获得 110 亿美元融资首笔，估值 1.25 万亿美元","summary":"OpenAI 获得约 110 亿美元新融资，这是总额最高可达 200 亿美元一轮的首笔，投后估值 1.25 万亿美元。OpenAI 原计划以 1.4 万亿美元估值融资 300 亿美元，因 AI 板块抛售而缩水，投资方包括 Coatue、SoftBank、红杉、a16z 等，另在通过投行引入富裕个人投资者。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T09:45:23.000Z","url":"https://the-decoder.com/openai-lands-an-11-billion-funding-round-but-has-to-court-dentists-for-more-capital/"},{"id":"rwtxr2ojxyp783mxrtbwcsgpx","title":"OpenAI 新一轮融资 110 亿美元，估值达 1.25 万亿美元","summary":"据 Bloomberg 报道，OpenAI 在新一轮融资中再筹 110 亿美元，估值达 1.25 万亿美元，此前 3 月曾以 8520 亿美元估值融资 1220 亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T23:46:18.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1029380/openai-1-25-trillion-investment-valuation"},{"id":"nzv1dbnt3om3p6ff8fujiq0ga","title":"OpenAI 传已融资 110 亿美元，估值 1.25 万亿美元","summary":"据 Bloomberg 援引知情人士报道，OpenAI 在新一轮融资中已募得 110 亿美元，估值达 1.25 万亿美元，该轮尚未关闭，未来数周内预计完成，总额可能约 200 亿美元，低于此前传出的 300 亿美元目标。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T22:53:46.000Z","url":"https://techcrunch.com/2026/11/06/openai-reportedly-raises-an-additional-11-billion-at-a-1-25-trillion-valuation/"},{"id":"m45kaixmfb2554qlzxbpnir36","title":"Bloomberg：OpenAI 完成 110 亿美元融资首批到账，估值达 1.25 万亿美元","summary":"据 Bloomberg，OpenAI 完成 110 亿美元新融资，这是估值 1.25 万亿美元一轮的首笔资金。投资者当日已打款，剩余部分总额最高 200 亿美元，预计数周内到账。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T21:10:13.000Z","url":"https://x.com/rohanpaul_ai/status/2118813225336873181"}]},"5bb5d3ee-b9ff-4cb4-8df8-d487d6bc5b78":{"publicId":"5bb5d3ee-b9ff-4cb4-8df8-d487d6bc5b78","title":"Meta在Muse推出spaces并升级模型","status":"active","sourceCount":12,"reportCount":21,"firstReportAt":"2026-11-06T07:00:00.000Z","latestAt":"2026-11-07T07:40:53.263Z","latest":"Meta 推出基于 Muse Wonder 训练的现有模型专用版本，主动记忆与主动专注能力全面下放","digest":"Meta在Muse应用中推出spaces：用户描述规划器、追踪器、游戏等需求，Muse会直接在应用内生成可交互的类应用体验，用户可决定它放在哪个标签页、何时显示。Meta称spaces自发布起在Muse所有可用地区开放，连接相关应用后会在后台更新价格、日期等信息；分享空间以支持协作仍在探索中。\n\n同日，扎克伯格称Meta为Muse和Meta AI升级模型，把Muse Wonder中的Active Memory和Active Focus开放给所有用户。Meta称，新专用模型在Muse中遗忘关键信息的概率降低2.4倍，约束变化时摆脱卡壳的改善为67%；在Meta AI中则能更好地拆解复杂问题、提出更精准的追问并适应用户改变方向。这些效果数据来自Meta方面的说法。\n\nIT之家报道称，Muse中的新模型优先向订阅用户开放，订阅价格为每月20美元或100美元，Muse Wonder Full仅面向Muse Code订阅用户开放。Meta研究博客另称，该专用模型使Personal Superintelligence Index得分从38%提升到47%。","digestUpdatedAt":"2026-11-07T08:01:05.243Z","reports":[{"id":"fbu4qxa735fxt2wlh3tshx5j9","title":"Meta 推出基于 Muse Wonder 训练的现有模型专用版本，主动记忆与主动专注能力全面下放","summary":"Meta 于当地时间 11 月 6 日宣布推出基于 Muse Wonder 训练的现有模型专用版本，全面推送给 Muse 与 Meta AI 用户，并下放主动记忆（Active Memory）与主动专注（Active Focus）两项特性。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T07:40:53.263Z","url":"https://www.ithome.com/1/023/744.htm"},{"id":"e1hkomdfzs7pogzav4cwc77wr","title":"Muse 最佳功能之一：Spaces 上线","summary":"Muse 最棒的功能之一！\n\nSpaces 来了。描述一个规划器、追踪器、游戏，或任何你需要的东西，Muse 会直接把它构建到应用里。把它固定到标签页，随时回来，它都已经是最新的。","sourceName":"X：Christine Awad（Meta，Muse 设计） (@christinesed)","firstParty":false,"publishedAt":"2026-11-06T22:37:46.000Z","url":"https://x.com/christinesed/status/2118835259236294992"},{"id":"n39uxtnh6dug6ex0vh8wiqmaz","title":"Meta 在 Muse 应用中推出 spaces","summary":"今天我们推出 spaces，这是一种在 Muse 应用内设计自定义体验的方式——从追踪孩子活动和作业的学校仪表盘，到汇集截止日期和发票的自由职业者中心。\n\nhttps://about.fb.com/news/2026/11/introducing-spaces-customize-muse-app/","sourceName":"X：Meta Newsroom (@MetaNewsroom)","firstParty":false,"publishedAt":"2026-11-06T21:21:27.000Z","url":"https://x.com/MetaNewsroom/status/2118816054281699651"},{"id":"cgwhg7w4jtgr1y99t89bci5t3","title":"Muse 用一句话搭建应用空间","summary":"创建一个空间非常简单。描述你想要的内容，Muse 就会把它构建到应用里，你还可以随时继续提出修改。","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T20:11:08.000Z","url":"https://x.com/Muse/status/2118798358261424598"},{"id":"v5vjx4aobiuh1oq96u26e5t4m","title":"Muse 推出 Spaces 自定义功能","summary":"为任何事物建一个空间，把它放进你的标签栏……这次更新后，你可以围绕自己关心的内容彻底重塑这款应用。\n\n你可以自定义每个新空间，也能自定义应用本身的结构。🎨🛠️","sourceName":"X：Alex Cornell（Meta，Muse 产品设计负责人） (@alexcornell)","firstParty":false,"publishedAt":"2026-11-06T19:16:35.000Z","url":"https://x.com/alexcornell/status/2118784629193036098"},{"id":"brr44mygbv5ze0dprgyu0f5it","title":"Muse 上线 Spaces 自定义应用功能","summary":"Spaces 来了。描述一个规划器、追踪器、游戏，或任何你需要的东西，Muse 会直接把它构建到应用里。把它固定到你的标签页，随时回来，它都已经是最新的。","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T19:08:01.000Z","url":"https://x.com/Muse/status/2118782474486501510"},{"id":"f39jep1clmad925kdw8wrjteo","title":"Meta 推出 Spaces，用于与 Muse 智能体按项目协作","summary":"Meta 为其 Muse 智能体推出新功能 Spaces，用户可在侧边栏按主题建立独立对话空间，Muse 会围绕特定目标代为推进，如度假规划、礼物追踪或婚礼策划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T18:44:20.000Z","url":"https://techcrunch.com/2026/11/06/meta-introduces-spaces-a-new-way-to-collaborate-with-your-muse-agent/"},{"id":"u1t08iv9a4xlqlxsehgsi9ixv","title":"Meta Muse 团队分享 spaces 功能成果","summary":"为团队在 spaces 上完成的工作感到无比自豪！","sourceName":"X：Christine Awad（Meta，Muse 设计） (@christinesed)","firstParty":false,"publishedAt":"2026-11-06T18:42:45.000Z","url":"https://x.com/christinesed/status/2118776115141771618"},{"id":"y63iuulmd6zqa0f6325sh95y9","title":"Muse 用 spaces 打造感恩节烹饪指挥中心","summary":"最近我迷上了（往好处说？）规划感恩节做什么菜。这是我目前每周都会回来处理几次的任务，所以 Muse 帮我建了一个 space 来规划它、做好准备，它已经准备好在大日子当天成为我的指挥中心。\n\n我们打造 spaces，是为了让你做的工具能成为 Muse 本身的一部分。描述你需要什么，然后把它变成你的主标签页之一。","sourceName":"X：David Singleton（Meta MSL 工程副总裁，Muse） (@dps)","firstParty":false,"publishedAt":"2026-11-06T18:18:08.000Z","url":"https://x.com/dps/status/2118769921933062601"},{"id":"ong9nniyluwyzsd864rc4vxkl","title":"Meta 将 Muse Wonder 专项模型接入 Muse 和 Meta AI","summary":"Meta 推出用 Muse Wonder 训练的专项模型，接入 Muse 和 Meta AI，包含 Active Memory 和 Active Focus 两项能力。在 Muse 中，关键信息遗忘减少 2.4x，约束变化时摆脱卡壳的改善为 67%；Meta AI 则能更好地拆解复杂问题、提出更精准的追问并适应用户改变方向。","sourceName":"X：AI at Meta (@AIatMeta)","firstParty":false,"publishedAt":"2026-11-06T18:14:23.000Z","url":"https://x.com/AIatMeta/status/2118768974779634084"},{"id":"m3i39avenmad9qywqoncw99lt","title":"Meta Muse AI 推出自定义 spaces 功能，可生成类应用体验","summary":"Meta 为 Muse AI 助手推出名为 spaces 的新功能，用户可通过描述生成购物中心、学校看板、音乐追踪、问答游戏等类应用体验并直接在应用内交互。将 space 连接相关应用后，Muse 会在后台更新价格、日期等信息；用户可勾选、加笔记和编辑，把它加入侧边栏、移入主标签页或按时间安排显示。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T18:10:10.000Z","url":"https://www.theverge.com/tech/1028871/meta-muse-ai-spaces"},{"id":"lk4nacxtthqzmhs18hpq2dhd3","title":"扎克伯格宣布 Muse 与 Meta AI 模型升级，推出 Active Memory 和 Active Focus","summary":"Mark Zuckerberg 宣布为 Muse 和 Meta AI 升级模型，将 Muse Wonder 中的 Active Memory 和 Active Focus 带给所有用户。官方称新专用模型遗忘关键信息的概率降低 2.4 倍，自我纠错和完成日常任务的能力提升 67%，减少重复输入和卡死情况，详情见 research.meta.ai 博客。","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-06T18:08:36.000Z","url":"https://x.com/finkd/status/2118767522782626104"},{"id":"ikff402u44w98djuk0e2gl67l","title":"Muse 展示 Instagram 收藏餐厅空间","summary":"今晚的空间特别推荐：你在 Instagram 上收藏却从未去过的每一家餐厅，附带价格、评分等更多信息 🍽️\n\n这些只是帮你入门的几个想法，但还有充足的空间（space）容纳更多。你会构建什么？","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:32.000Z","url":"https://x.com/Muse/status/2118767000260337895"},{"id":"oy5a39pb7ldthggq5jdrd85m5","title":"Muse 用 spaces 管理日常待办","summary":"事情太多太乱时，spaces 能帮忙处理生活中反复出现的待办事项。跟踪它们、查看到期时间，还能让 Muse 来帮忙 💈","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:31.000Z","url":"https://x.com/Muse/status/2118766995478827075"},{"id":"r7dbn1rjxah7ycf9ullzxwcp2","title":"Muse 节日购物按人整理","summary":"节日购物，按人整理：这个空间会记录尺码、预算，以及你从七月以来的每一个想法 🎁","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:30.000Z","url":"https://x.com/Muse/status/2118766993474216373"},{"id":"t510nwfzwnkr0s3dkie1kz2x3","title":"Muse 帮你盯紧所有上架信息","summary":"就差一枚硬币就能凑齐整套？这个空间帮你盯着所有上架信息 🪙","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:29.000Z","url":"https://x.com/Muse/status/2118766989279703429"},{"id":"uuyre0mg36145ktp60f7dknet","title":"Meta 空间内打造 Jolly Jump 游戏","summary":"无需游戏引擎，照样没问题。Jolly Jump 完全是在一个空间里构建出来的，你的创意也可以 👾","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:29.000Z","url":"https://x.com/Muse/status/2118766987576750427"},{"id":"af5ius9by5pguaqq44h9mrn28","title":"Meta 展示 Muse 应用自定义空间设计","summary":"设计专属于你的 Muse 应用。\n\n为任何你想要的内容构建空间，挑选标签页里放什么，甚至设定它们何时出现。\n\n以下是我们目前做的一些示例 ↓","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:28.000Z","url":"https://x.com/Muse/status/2118766983936197072"},{"id":"qu9pjazhrhr98lui6mvgz333w","title":"Meta Muse 空间功能体验","summary":"最近在玩 Muse 里的空间功能——告诉 Muse 你需要什么，它就能帮你搭建出来。\n\n我做了一个烧烤游戏、一个活动追踪器，还有一个家居控制面板。\n\n很期待看到大家能做出什么。","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-06T18:01:39.000Z","url":"https://x.com/finkd/status/2118765774034579808"},{"id":"f3hogz1c4bmgbcwblqblumxpv","title":"Meta 在 Muse 应用中推出 spaces 自定义个性化体验","summary":"Meta 推出 spaces，一种在 Muse 内通过描述想法构建个性化体验的交互方式，例如节日礼物追踪、每日文字游戏或 DIY 规划板。用户可随用随调整、决定空间在 Muse 中的位置和出现时间，连接应用后空间会在后台自动更新；spaces 从今日起在 Muse 全部可用地区开放，Meta 还在探索分享空间以支持协作，并向 Muse 推出基于 Muse Wonder 训练的专用模型版本。","sourceName":"Meta：Newsroom · AI（RSS）","firstParty":true,"publishedAt":"2026-11-06T18:00:58.000Z","url":"https://about.fb.com/news/2026/11/introducing-spaces-customize-muse-app/"},{"id":"fjuidf0zii7na78sxru5il7pr","title":"Meta 将基于 Muse Wonder 训练的专用模型上线 Muse 与 Meta AI","summary":"Meta 宣布把基于 Muse Wonder 训练的专用模型推向 Muse 和 Meta AI 用户，Personal Superintelligence Index 得分从 38% 提升到 47%。","sourceName":"Meta AI：Research Blog（网页）","firstParty":true,"publishedAt":"2026-11-06T07:00:00.000Z","url":"https://research.meta.ai/blog/specialized-models-for-muse-and-metaai"}]},"4648eb5b-d72a-42ef-ae63-e963d1fccca0":{"publicId":"4648eb5b-d72a-42ef-ae63-e963d1fccca0","title":"Nous Research 微调 Qwen 推出 Arete-27B","status":"active","sourceCount":2,"reportCount":2,"firstReportAt":"2026-11-07T12:32:45.000Z","latestAt":"2026-11-08T04:45:59.000Z","latest":"Nous Research 发布 Arete-27B，将 Qwen3.8-27B 宣传性回答从 22% 降到 0.9%","digest":"Nous Research 对阿里巴巴 Qwen3.8-27B 做纯监督微调，发布开源权重模型 Arete-27B，权重、评测和训练数据均公开，采用与基座模型一致的 Apache 2.0 许可。\n\nNous Research 称，该模型旨在体现“西方价值观”而非北京的官方立场。在其自建的 803 条提示评测中，含宣传内容的回答占比从 22% 降至 0.9%，事实得分从 2.32 升至 2.98。这些数字来自 Nous Research 自己的评测，并非独立验证的效果。","digestUpdatedAt":"2026-11-08T05:29:05.642Z","reports":[{"id":"wcf67hswu4ndva9c1zqjrbyrm","title":"Nous Research 发布 Arete-27B，将 Qwen3.8-27B 宣传性回答从 22% 降到 0.9%","summary":"Nous Research 发布 Arete-27B，这是对 Qwen3.8-27B 的纯监督微调，在其 803 条提示的自建评测中，含宣传内容的回答从 22% 降至 0.9%，事实得分从 2.32 升至 2.98。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-08T04:45:59.000Z","url":"https://www.marktechpost.com/2026/11/07/nous-research-arete-27b-qwen3-8-27b-propaganda-fine-tune/"},{"id":"nsy92pj0h1aiwvp0wdqkzb1cc","title":"Nous Research 微调 Qwen3.8-27B 推出 Arete-27B，宣传率从 22% 降至 0.9%","summary":"Nous Research 对阿里巴巴 Qwen3.8-27B 进行约 5300 万 token 的监督微调，发布开源权重模型 Arete-27B，宣传性回答占比从 22% 降至 0.9%，事实得分从 2.32 升至 2.98。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T12:32:45.000Z","url":"https://the-decoder.com/state-propaganda-in-some-chinese-ai-models-is-only-a-thin-layer-that-fine-tuning-can-strip-away/"}]},"6eeb5785-1785-4258-bcdf-95eccfdc5d8c":{"publicId":"6eeb5785-1785-4258-bcdf-95eccfdc5d8c","title":"GPT-6.1 Sol参与小鼠脑手术定位实验","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-08T07:05:49.673Z","latestAt":"2026-11-08T07:05:49.673Z","latest":"GPT-6.1 Sol 连续参与三次活体小鼠脑手术，定位误差从 0.6 毫米降至 0.3 毫米","digest":"Exin Therapeutics 联合创始人兼 CEO 加布里埃尔·奥卡尼亚-桑特罗称，GPT-6.1 Sol 连续三次参与活体小鼠脑部手术中的 Bregma 和 Lambda 解剖标志定位，定位误差从 0.6 毫米降至 0.3 毫米。\n\n据《WIRED》报道，每次操作由外科医生纠正后保存图像与测量数据，供下一次参考。该结果由奥卡尼亚-桑特罗于 11 月 5 日在 X 上公布，目前仅涉及小鼠实验中的标志定位环节。","digestUpdatedAt":"2026-11-08T07:36:14.086Z","reports":[{"id":"uhi0dbgdjc32uma8nu41ftguf","title":"GPT-6.1 Sol 连续参与三次活体小鼠脑手术，定位误差从 0.6 毫米降至 0.3 毫米","summary":"据《WIRED》报道及 Exin Therapeutics CEO 于 11 月 5 日在 X 公布的结果，GPT-6.1 Sol 连续三次参与活体小鼠脑部手术中的 Bregma 和 Lambda 解剖标志定位，每次由外科医生纠正后保存图像与测量数据供下次参考。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-08T07:05:49.673Z","url":"https://www.ithome.com/1/023/900.htm"}]},"37046dc2-8e44-4949-965c-ef07dbd0b13e":{"publicId":"37046dc2-8e44-4949-965c-ef07dbd0b13e","title":"OpenAI 发布 Images 2.6，ChatGPT 可直接生成 GIF","status":"active","sourceCount":16,"reportCount":26,"firstReportAt":"2026-11-04T00:00:00.000Z","latestAt":"2026-11-07T11:22:20.000Z","latest":"GPT-Image-2.6 实测：10 个 GIF 玩法与提示语分享，附人脸漂移与成本问题","digest":"OpenAI 发布 Images 2.6，ChatGPT 首次能直接生成 GIF 动图：用户可用提示词或上传图片生成，并调整播放速度、逐帧编辑和分享。该功能随 Images 2.6 向所有套餐的 ChatGPT 和 Codex 用户推送，覆盖网页、桌面和移动端；新版还支持保存人物、宠物或角色的参考图，供后续创作复用。\n\nAPI 同步上线两款图像模型：GPT-Image-2.6 Flare 主打速度，low 画质下最快 6 秒出图；GPT-Image-2.6 Sunburst 主打中高质量与多次编辑间的细节一致性。OpenAI 称两者生成速度比前代快 50%，并支持图像标记与 SVG 导出。据 MarkTechPost 引述模型页面，两款模型按 token 计费且价格相同：文本输入每百万 token 5 美元、图像输入 8 美元、图像输出 30 美元，调整复杂度不另收费。fal、Higgsfield、Krea 等第三方平台也已上线该模型，Higgsfield 对 Pro、Plus、Max、Ultra 套餐的新用户提供 7 天无限使用。\n\n性能数据存在不同口径：OpenAI 引用的 DesignArena 数据称 Sunburst 在 Image Arena 排名第一、Flare 比前代快 2.6 倍；Arena 随后公布 Sunburst（Medium）在文生图榜排第 2、Flare（Medium）排第 4，并称新模型比 2.5 快 2 倍以上、最低延迟约 5 秒。Artificial Analysis 在 max 画质、复杂度取 API 默认 high 的条件下测试，称两款模型在 AA-Image-T2I v2.1 和 AA-Image-Editing v2.1 上分列第一、二名。","digestUpdatedAt":"2026-11-07T11:35:15.694Z","reports":[{"id":"xkzbtxxcskce5dgl0wjvf67fo","title":"GPT-Image-2.6 实测：10 个 GIF 玩法与提示语分享，附人脸漂移与成本问题","summary":"作者整理 GPT-Image-2.6 的 10 个 GIF 玩法并附提示语，包括黏土定格动画、抽象表情包、剪辑贴纸、loading 图、PPT 动态图表、产品演示、2.5D 爆炸图等，另测试了跨对话角色记忆、结构引出线拆解图和纯矢量 SVG 输出三项新能力。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-07T11:22:20.000Z","url":"https://mp.weixin.qq.com/s/AFBcZGMlNJxBmlqhHEPOSg"},{"id":"fqj1p7582px47e6468ofmr24v","title":"GPT-Image-2.6 支持生成 GIF","summary":"每个人，或每个团队，都能用 GPT-Image-2.6 创作 GIF。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-06T23:46:33.000Z","url":"https://x.com/OpenAIDevs/status/2118852567509909716"},{"id":"pqbbgx5sn86iy7v4izf1qv49z","title":"Artificial Analysis 实测 GPT Image 2.6 图像生成与编辑表现","summary":"Artificial Analysis 对 OpenAI 于 11 月 4 日发布的 GPT Image 2.6 进行了基准测试，两款模型在 AA-Image-T2I v2.1 和 AA-Image-Editing v2.1 上分列第一、二名。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-06T23:40:40.000Z","url":"https://x.com/ArtificialAnlys/status/2118851088111865983"},{"id":"c2p75q23kddn0btdx6kif3d4o","title":"Krea 上线 GPT Image 2.6","summary":"GPT Image 2.6 现已在 Krea 上线。\n\n图像生成速度提升 50%，支持单张参考图编辑，还能把图像做成 GIF 动起来。\n\n立即试用 👇","sourceName":"X：Krea AI (@krea_ai)","firstParty":false,"publishedAt":"2026-11-06T23:32:27.000Z","url":"https://x.com/krea_ai/status/2118849021796307151"},{"id":"n0j82m65z6if232ik2xh30yw3","title":"fal 上线 GPT Image 2.6 生成 GIF","summary":"用 GPT Image 2.6 生成 GIF，现已在 fal 上线。\n\n可将任意提示词或图片转为动态 GIF，自定义单帧并创建无缝循环。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-06T18:51:10.000Z","url":"https://x.com/fal/status/2118778232673816649"},{"id":"zz0hwq5je59rkzmhpbbuf5v83","title":"fal 上线 gpt-image-2.6 可试用","summary":"立即试用：https://fal.ai/gpt-image-2.6","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-06T18:51:10.000Z","url":"https://x.com/fal/status/2118778235106566382"},{"id":"mcab7bd12n30tbwsd97xqpizh","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst，新增 GIF、SVG 导出和 6 秒生成","summary":"OpenAI 在 ChatGPT、Codex 和 API 上线 Images 2.6，API 端分为 GPT-Image-2.6 Flare 和 Sunburst 两个模型，官方称生成速度比此前快 50%，Flare 在低质量下最快 6 秒出图。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T07:03:17.000Z","url":"https://www.marktechpost.com/2026/11/04/openai-gpt-image-2-6-flare-sunburst/"},{"id":"eoav9ea3p1g5xhf2a57dga4nx","title":"ChatGPT Images 2.6 发布，新增 GIF 与参考图功能","summary":"Greg Brockman 转发 OpenAI 公告宣布 ChatGPT Images 2.6 上线。新版本支持 GIF 和参考图像，另有两款新模型将进入 API，图像生成速度提升 50%。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T02:54:05.000Z","url":"https://x.com/gdb/status/2118174986544488876"},{"id":"rxbccxa9of5e3e4v07auo0kmp","title":"OpenAI 发布 ChatGPT Images 2.6，支持生成动图和复用参考图","summary":"OpenAI 发布 ChatGPT Images 2.6，可将提示词和图片生成动画 GIF。新版本还支持保存自己、宠物和角色的参考图，在新创作中直接复用而无需重复上传。Images 2.6 当天起面向所有套餐开放，覆盖网页、桌面和移动端的 ChatGPT 与 Codex。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-05T02:27:14.000Z","url":"https://x.com/ChatGPT/status/2118168231617700199"},{"id":"x62bu2fgvqqixlotmawy3zmxv","title":"OpenAI 发布 GPT Image 2.6 Sunburst 与 Flare，速度提升近 2 倍","summary":"Arena 宣布 OpenAI 的 GPT Image 2.6 Sunburst 和 Flare 上线，据称比 GPT Image 2.5 快 2 倍以上，最低延迟可达 5 秒。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T00:31:20.000Z","url":"https://x.com/arena/status/2118139063345787124"},{"id":"umgmuegnck66u7urzxbiruhum","title":"Higgsfield AI 推出 GPT-Image-2.6 限免活动","summary":"优惠详情：\n\n> GPT-Image-2.6 Flare 和 Sunburst 无限使用 7 天\n> 面向 Pro、Plus、Max 和 Ultra 套餐的新用户","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:43.000Z","url":"https://x.com/higgsfield/status/2118134127086215499"},{"id":"lcdap1o18bh6bt70ij66nakij","title":"Higgsfield 上线 GPT Image 2.6，新用户 7 天无限使用","summary":"Higgsfield 宣布 GPT Image 2.6 已上线，新用户可 7 天无限使用。功能包括把提示词或图片转成 GIF、保存参考图随时复用、通过 markup 细化并导出 SVG。OpenAI 此前介绍 ChatGPT Images 2.6 新增 GIF 和参考图功能，另有两款 API 模型将带来 50% 更快的图像生成。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:42.000Z","url":"https://x.com/higgsfield/status/2118134123533623424"},{"id":"hgl8n52jtawmq03wmiy5ksgf4","title":"fal 上线 OpenAI gpt-image-2.6 的 Sunburst 与 Flare 图像模型","summary":"fal 上线 OpenAI gpt-image-2.6 的四个模型入口，包括 Sunburst Text-to-Image、Sunburst Edit、Flare Text-to-Image 和 Flare Edit，并给出 fal.ai 上的试用链接。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:53.000Z","url":"https://x.com/fal/status/2118127876843205032"},{"id":"ckoor7mjziavjeua4n36wjaxc","title":"fal 上线 GPT Image 2.6","summary":"fal 宣布 GPT Image 2.6 已可在其平台使用。新能力包括在图片上画圈、箭头和标注来引导编辑，文本生成图像和编辑均支持输出动画 GIF，并提供从 low 到 max 共五档推理强度。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:52.000Z","url":"https://x.com/fal/status/2118127874926407952"},{"id":"w5zdd70hao0x58ifak6pgf9pz","title":"OpenAI 推出 Images 2.6 模型，ChatGPT 支持直接生成和编辑 GIF 动画","summary":"OpenAI 随新 Images 2.6 模型为 ChatGPT 推出 GIF 生成功能，用户可通过提示词或上传照片创建 GIF，并调整动画速度、编辑单个帧和分享。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-04T23:41:17.163Z","url":"https://www.ithome.com/1/022/486.htm"},{"id":"o915zd1u1eq13gyo9x3nsgoq8","title":"OpenAI 发布 Images 2.6 并向所有档位开放 Codex","summary":"OpenAI 宣布 Images 2.6 今日起在 ChatGPT 中可用，Codex 同时面向所有档位开放，覆盖 web、桌面和移动端。GPT-Image-2.6 Flare 和 Sunburst 也已在 API 中提供，详情见官方页面 https://openai.com/index/introducing-images-2-6/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:19.000Z","url":"https://x.com/OpenAI/status/2118124966055223755"},{"id":"v4926jbeulchfze584bf3em1r","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst 两款开发者图像模型","summary":"OpenAI 发布面向开发者的两款新图像模型 GPT-Image-2.6 Flare 和 Sunburst。Flare 最快六秒即可生成图像；Sunburst 主打更高质量的生成和跨编辑的一致性。两者还支持图像标记与 SVG 导出，便于进一步精修和使用生成结果。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:18.000Z","url":"https://x.com/OpenAI/status/2118124964197114039"},{"id":"lgg076xbmrpmfpdoi1xa50pf0","title":"ChatGPT Images 2.6 支持生成动图 GIF","summary":"GIF 动图！\n\n用 ChatGPT Images 2.6，把提示词或图片变成动态 GIF。\n\n可调整速度、编辑单帧，还能循环分享。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:16.000Z","url":"https://x.com/OpenAI/status/2118124953832935810"},{"id":"jkz26nto61yp9panc1o0bj38s","title":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 与参考图功能","summary":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 和参考图功能。同时宣布两款新模型即将登陆 API，图像生成速度提升 50%。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:14.000Z","url":"https://x.com/OpenAI/status/2118124944928432327"},{"id":"fgh2jnkm6pmhmgzuj6027pu43","title":"OpenAI 教你用静态角色制作循环 GIF","summary":"把静态角色、精灵图或吉祥物做成循环 GIF，用于视频、游戏或应用。\n\n从美术素材开始，描述你想要的动效。试试挥手、回头或胜利舞，并让动作循环回起始姿势。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124755442151684"},{"id":"pgdl5xjrrav478d5ctidbvt7i","title":"OpenAI 介绍 GPT Image 2.6 Flare 低画质下最快六秒生成图像","summary":"OpenAI 介绍 GPT Image 2.6 Flare 在画质设为 low 时最快六秒即可生成一张图像。引用 @DesignArena 数据称，GPT Image 2.6 Sunburst 在 Image Arena 排名第一，超过前代 2.5 Sunburst，其中 2.6 Flare 比前代快 2.6 倍，2.6 Sunburst 快 1.15 倍。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124757639966858"},{"id":"j7mpmw4fk1ud0u49x0gjzubyo","title":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API","summary":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API。新 API 图像模型 Flare 和 Sunburst 生成速度比之前快 50%；在 medium 或 high 质量下，Sunburst 能在多次编辑间保持细节更一致。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:28.000Z","url":"https://x.com/OpenAIDevs/status/2118124753340756055"},{"id":"xe7e23trxt0hyvsvlq5rtrmui","title":"OpenAI 发布 Images 2.6，ChatGPT 支持文本和照片生成动画 GIF","summary":"OpenAI 基于新模型 Images 2.6 在 ChatGPT 中上线 GIF 生成功能，正向网页、桌面和移动端所有 ChatGPT 和 Codex 用户推送。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-04T19:44:20.000Z","url":"https://the-decoder.com/chatgpt-can-now-turn-text-prompts-and-photos-into-animated-gifs-with-openais-images-2-6-model/"},{"id":"zsx5ofvv8iyuit5ytfvqvfllu","title":"OpenAI 为 ChatGPT 上线 GIF 生成并发布 Images 2.6 模型","summary":"OpenAI 随 Images 2.6 模型为 ChatGPT 上线 GIF 生成，可单步生成动图并调整播放速度、逐帧编辑和分享，此前 ChatGPT 无法一步原生生成 GIF。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-04T18:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1026474/openai-chatgpt-animated-gifs-images-2-6"},{"id":"hoc5e7f6m140ydnyhciavbgwj","title":"OpenAI 发布 GPT-Image-2.6（Sunburst 与 Flare）系统卡","summary":"OpenAI 发布 ChatGPT Images 2.6 系统卡，涵盖 GPT-Image-2.6 Sunburst 与 GPT-Image-2.6 Flare 的训练数据、安全评估与防护措施。","sourceName":"OpenAI：部署安全与系统卡（网页）","firstParty":true,"publishedAt":"2026-11-04T07:00:00.000Z","url":"https://deploymentsafety.openai.com/chatgpt-images-2-6"},{"id":"wwltahauj3uhzwy9yizi2i6f3","title":"OpenAI 发布 Images 2.6，生成提速 50% 并新增 GIF 动画能力","summary":"OpenAI 在 ChatGPT、Codex 和 API 中推出 Images 2.6，图像生成速度比之前快 50%，并支持用 GIF 为图像添加动画。API 提供 GPT-Image-2.6 Flare（低质量下最快 6 秒出图）和 GPT-Image-2.6 Sunburst（中高质量下更精细）两个模型。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T00:00:00.000Z","url":"https://openai.com/index/introducing-images-2-6"}]},"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5":{"publicId":"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5","title":"Thinking Machines 发布 Inkling 2 Small，权重下周开源","status":"active","sourceCount":11,"reportCount":19,"firstReportAt":"2026-11-04T16:00:00.000Z","latestAt":"2026-11-07T16:31:00.000Z","latest":"Vals AI 研究：Thinking Machines 的 Inkling 2 Small 在基准测试中爆粗口 316 次","digest":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，即日起通过 Tinker 平台提供微调和推理，权重初期闭源。公司称，完整权重计划于下周以 Apache 2.0 许可开放，前提是完成外部安全测试和红队评估。\n\n该模型为 594B 总参数、17B 激活的 MoE，支持图像输入和 1M token 上下文。Artificial Analysis 称其在 Intelligence Index v5.0.1 上得 31 分，较前代提升 18 分；若权重按计划开源，按当前排名将成为中国以外得分最高的开源权重模型。ARC Prize 称其在 ARC-AGI-2 得 81.7%、ARC-AGI-1 得 96.5%，在其评估过的所有开源权重模型中两项均为最好，ARC-AGI-3 结果待测试完成后公布。Tinker 定价为每百万输入/输出 token 0.30 美元和 1.00 美元，缓存输入每百万 token 0.03 美元。\n\nArena 对同一模型给出两组 Code Arena: WebDev 数据：AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一；另一条称其以 1648 分在实验室中排第 8，并称权重发布后将成为美国开源模型第 1。公司还称其擅长长周期任务、能以视觉方式检查自身工作，用户可自行微调或让模型自主编排微调流程。公司员工 Karina Nguyen 分享的案例称，该模型智能体在财务尽调任务中自行下载并解析 PSEG 10-Q，发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。Vals AI 研究人员称，读取该模型在 13 个基准、2655 次运行中的思考日志后发现，50 次运行出现 “fuck” 及其变体共 316 次，其中 241 次来自两次失控运行。上述能力与得分均为公司或相关机构说法，尚未见独立验证。","digestUpdatedAt":"2026-11-07T16:43:46.908Z","reports":[{"id":"h1e0zbyqc8p5ps481naunojc2","title":"Vals AI 研究：Thinking Machines 的 Inkling 2 Small 在基准测试中爆粗口 316 次","summary":"Vals AI 研究人员读取 Thinking Machines 的 Inkling 2 Small 在 13 个基准、2655 次运行中的思考日志，发现 50 次运行出现 \"fuck\" 及其变体，共 316 次，其中 241 次来自两次失控运行。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-07T16:31:00.000Z","url":"https://the-decoder.com/thinking-machines-inkling-2-small-drops-316-f-bombs-across-benchmark-runs/"},{"id":"r9vhw2sw7ngvttl2nuw8n2um5","title":"Inkling 2 Small 登顶 WebDev 开源榜","summary":"在 Code Arena: WebDev 中，@thinkymachines 的 Inkling 2 Small 位列数据与分析类第 5 名！\n\n在所有开源模型中，它在该类别将排名第 1。相比其前代 Inkling-Small（第 92 名），该类别提升了 +220 分。\n\n总体而言，Inkling 2 Small 在 Code Arena: WebDev 中相比 Inkling-Small 提升了 +240 分。它在所有类别中都展现出大幅进步。\n\n再次祝贺 @thinkymachines 团队！","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-06T21:41:38.000Z","url":"https://x.com/arena/status/2118821131268542656"},{"id":"ig2uhv0ty94xcuylusksz6e8j","title":"Arena 榜单显示 Inkling 2 Small 以 1648 分位列 Code Arena: WebDev 实验室第 8","summary":"Arena 公布 thinkymachines 的 Inkling 2 Small 进入 Code Arena: WebDev 榜单，以 1648 分在实验室中排名第 8，权重发布后将成为美国开源模型第 1。该模型现已在 Tinker 上开放微调和推理，完整权重即将发布；此前引用帖中 1654 分版本显示其领先第 2 名 Meta Muse Spark Open 128 分，全球开源模型中排第 4。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-06T20:16:00.000Z","url":"https://x.com/arena/status/2118799582092288255"},{"id":"lw2hzp0hhmruk1mcbyn5p568d","title":"ARC-AGI-3 评测结果待测试完成后公布","summary":"@thinkymachines ARC-AGI-3 的评测在操作上更为密集；测试完成后我们将分享结果。\n\n完整的 ARC-AGI-1 和 ARC-AGI-2 结果：https://arcprize.org/results/thinky-inkling-2-small","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788853850849780"},{"id":"scx0uniqq40o6783tgm1kbm6m","title":"ARC Prize 公布 Inkling 2 Small 评测结果","summary":"@thinkymachines - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- Inkling 2 Small 完整结果：https://arcprize.org/results/thinky-inkling-2-small","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788855318864211"},{"id":"vjq1vbniakkbxo874r83u27z0","title":"ARC Prize 公布 Inkling 2 Small 的 ARC-AGI-2 成绩，semi-private 得分从 40.14% 升至 81.67%","summary":"ARC Prize 对比 Thinky Machines 的 Inkling 2 Small 与 7 月 30 日发布的初代 Inkling Small 在 ARC-AGI-2 上的表现，semi-private 得分从 40.14% 翻倍以上至 81.67%。图表还显示 public 得分从 39.31% 升至 84.17%。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788852177322324"},{"id":"ybb8tr36f4xballoylrv50nhe","title":"Inkling 2 Small 在 ARC-AGI Verified 测得 81.7%，Thinking Machines 计划下周开放完整权重","summary":"ARC Prize 公布 Thinking Machines 的 Inkling 2 Small 在 ARC-AGI (Verified) 的成绩：ARC-AGI-2 得分 81.7%，每任务成本 $0.27；ARC-AGI-1 得分 96.5%，每任务成本 $0.08。据称其在其评估过的所有开源权重模型中 ARC-AGI-1 和 ARC-AGI-2 表现均为最好，Thinking Machines 计划下周发布完整权重。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:21.000Z","url":"https://x.com/arcprize/status/2118788850742911073"},{"id":"xer90akebatzhqzplx13ldjcm","title":"Thinking Machines 发布 Inkling 2 Small，称其为最强西方开放权重模型","summary":"Mira Murati 创立的 Thinking Machines 发布第二代模型 Inkling 2 Small，总参数 594B、激活 17B 的 MoE 模型。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T13:25:09.000Z","url":"https://the-decoder.com/thinking-machines-inkling-2-small-claims-top-spot-among-western-open-weight-models/"},{"id":"xbvw6hby8c4xtbbwkbr9el4s7","title":"Thinking Machines 发布 Inkling 2 Small：594B 总参 17B 激活 MoE，GB300 上 68 小时预训练","summary":"Latent Space 汇总多家信源报道 Thinking Machines 发布 Inkling 2 Small，594B 总参、17B 激活的多模态 MoE。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-06T10:35:21.000Z","url":"https://latent.space/p/ainews-inkling-2-small-17a-594b-trained-in-68-hours-on-12t-tokens-beating-muse-spark/"},{"id":"eil7g827qnurbw83ytbjpokhb","title":"Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活、1M 上下文","summary":"Thinking Machines Lab 发布第二代 Inkling 首款模型 Inkling 2 Small，为 594B 总参数、17B 激活的稀疏 MoE，支持文本与图像输入、1M token 上下文和可变推理强度。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-06T04:25:07.000Z","url":"https://www.marktechpost.com/2026/11/05/thinking-machines-inkling-2-small-release/"},{"id":"exer6wv2kt3nbwubog2yrjgh0","title":"Inkling 2 Small 自主改进模型能力","summary":"应用了 RSI 🚀","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-06T00:01:47.000Z","url":"https://x.com/karinanguyen/status/2118494016165777441"},{"id":"xpmyon7tezenro4k4fmlbf3th","title":"Thinking Machines 发布 Inkling 2 Small，Artificial Analysis 指数得分 31 并计划开源权重","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index v5.0.1 得分 31，较 Inkling Small 提升 18 分，计划以 Apache 2.0 发布权重，若落实将成为中国以外得分最高的开源权重模型。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-05T23:59:15.000Z","url":"https://x.com/ArtificialAnlys/status/2118493376186388530"},{"id":"c66xa3anti4ibc6om7fcq1owk","title":"Inkling 2 Small 进入 Code Arena: WebDev 榜单，1654 分约列美国开源模型第一","summary":"Arena 宣布 Thinking Machines 的 Inkling 2 Small 进入 Code Arena: WebDev，AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T23:55:05.000Z","url":"https://x.com/arena/status/2118492327887155680"},{"id":"dfl6x1foulmm0456amukc5na6","title":"Karina Nguyen 演示 Inkling 2 Small 在财务尽调任务中独立解析 PSEG 10-Q 并发现 12 亿美元抵押品释放","summary":"Karina Nguyen 分享一个 Inkling 2 Small 智能体的实测轨迹：当申报工具只返回 PSEG 的目录时，该智能体自行下载完整的 3.7MB 10-Q，用 Python 解析，并发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。引用的 @thoughtfullab 内容称其在 DiligenceBench 上表现良好，该模型为 594B 参数、17B 激活参数的 MoE，定价 $0.30/M 输入和 $1/M 输出 token。","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-05T23:53:36.000Z","url":"https://x.com/karinanguyen/status/2118491955239989515"},{"id":"o3kzzqpf35qwhqm7w9xvr1xuw","title":"Thinking Machines 发布 Inkling 2 Small 并上线 Tinker","summary":"Mira Murati 宣布 Inkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重即将开放。据引用的 Thinking Machines 官方内容，该模型在 AA Intelligence Index 上得 31 分，较前代大幅提升。","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-05T23:45:03.000Z","url":"https://x.com/miramurati/status/2118489804585509192"},{"id":"hca5pexdy88fstdlafrqet4iq","title":"Thinking Machines 发布 Inkling 2 Small","summary":"推出 Inkling 2 Small。在 AA Intelligence Index 上得分 31，相较前代大幅提升。\n\nInkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重发布计划于近期推出。\n\nhttps://thinkingmachines.ai/news/inkling-2-small","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489527362912566"},{"id":"j2wy2avc7gqke53hk08kztvy1","title":"Thinking Machines 介绍 Inkling 2 Small 的长任务与视觉自检能力，开放 Tinker 微调","summary":"Thinking Machines 介绍 Inkling 2 Small，称其擅长长周期任务、能以视觉方式检查自身工作，并可适配不同的 harness 和环境。用户可在 Tinker 上对其微调，或让 Inkling 2 Small 自主编排微调流程。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489528424104201"},{"id":"bu8612ca3e1uyxjppk56ef1wl","title":"Thinking Machines Lab 发布 Inkling 2 Small：594B 参数 MoE 模型，下周开放 Apache 2.0 权重","summary":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，为 594B 总参数、17B 激活的 MoE 模型，支持图像输入与 variable effort，Artificial Analysis Intelligence Index 得分 31。","sourceName":"Thinking Machines Lab：News（网页）","firstParty":true,"publishedAt":"2026-11-05T07:00:00.000Z","url":"https://thinkingmachines.ai/news/inkling-2-small/"},{"id":"aox2so3ad2v3skhpll59u9fxx","title":"Thinking Machines 发布 Inkling 2 Small，权重将开源为评分最高的中国以外开放权重模型","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index 得分 31，较 Inkling Small 提升 18 分；计划后续以 Apache 2.0 开放权重，若兑现将是中国以外评分最高的开放权重模型。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/thinking-machines-releases-inkling-2-small-highest-scoring-open-weights-model-outside-of-chinia-upon-weights-release-it"}]},"2861254b-d4a1-436b-934f-1c7a44583b7e":{"publicId":"2861254b-d4a1-436b-934f-1c7a44583b7e","title":"DeepSeek网页与API服务中断45分钟后恢复","status":"active","sourceCount":1,"reportCount":2,"firstReportAt":"2026-11-07T07:18:03.457Z","latestAt":"2026-11-07T08:48:00.363Z","latest":"DeepSeek 网页 / API 服务恢复正常，今天下午一度中断 45 分钟","digest":"11月7日15:11至15:56，DeepSeek网页与API服务出现部分中断，持续45分钟。用户对话时收到“服务器暂时不可用”提示，官方服务状态页显示正在排查问题。\n\n官方状态页随后显示问题已解决，服务恢复正常。此次中断仅涉及部分服务，并非全部不可用。","digestUpdatedAt":"2026-11-07T11:48:47.825Z","reports":[{"id":"ndfa03stgzpq05zqxrod8urrz","title":"DeepSeek 网页 / API 服务恢复正常，今天下午一度中断 45 分钟","summary":"DeepSeek 网页与 API 服务在 11 月 7 日 15:11~15:56 出现部分中断，持续 45 分钟，对话提示“服务器暂时不可用”。官方状态页显示问题已解决，服务已恢复。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T08:48:00.363Z","url":"https://www.ithome.com/1/023/758.htm"},{"id":"ob3k2pi4okhhltmfxgkavfjod","title":"DeepSeek 网页 / API 服务突发部分中断，提示“服务器暂时不可用”","summary":"DeepSeek 网页与 API 服务今日出现部分中断，对话时提示“服务器暂时不可用”。官方服务状态页面显示正在排查问题，中断已持续超 3 分钟，目前已恢复。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-07T07:18:03.457Z","url":"https://www.ithome.com/1/023/697.htm"}]},"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"纽时称中国情报人员接近黄仁勋，英伟达否认，国会要求简报","status":"active","sourceCount":5,"reportCount":6,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-06T23:00:44.000Z","latest":"美媒称中国国安招募 Megaspeed 高管 Alice Huang 刺探英伟达 CEO 黄仁勋","digest":"《纽约时报》援引匿名情报信源报道，美国情报机构约一年来监控新加坡 AI 云公司 Megaspeed 高管 Alice Huang（黄乐），怀疑她借与英伟达 CEO 黄仁勋的密切接触，为中国收集英伟达的计划以及游说特朗普政府放宽对华芯片出口的信息。报道还称，特朗普约一年前已获知相关情报，但未采取行动，部分原因是保护英伟达股价，以及他与黄仁勋关系密切。上述指控均未获独立证实。\n\n英伟达否认这一说法，称 Megaspeed 只是其区域云客户之一，黄乐与公司官员的接触属例行往来，云客户仅获得普通商业信息，不涉及国家安全相关信息；关于 Megaspeed 将 AI 芯片转运至中国的指控“去年已被彻底调查并证伪”，公司也未收到华盛顿方面的任何预警。此前美国商务部曾调查 Megaspeed 涉嫌向中国转售受限芯片。\n\n美国国会三个委员会的主席已致函黄仁勋，要求他就与黄乐的接触作闭门简报。","digestUpdatedAt":"2026-11-06T23:03:44.030Z","reports":[{"id":"neqabr3rrtmenaqmzqgt38p7q","title":"美媒称中国国安招募 Megaspeed 高管 Alice Huang 刺探英伟达 CEO 黄仁勋","summary":"据《纽约时报》报道，中国国家安全部招募了英伟达客户 Megaspeed 的高管 Alice Huang，目的是获取美国 AI 芯片信息，并\"可能影响该公司推动最先进芯片对华供应\"。Alice Huang 与英伟达 CEO 黄仁勋无亲属关系但关系\"密切\"，她还与技嘉等 AI 芯片行业高层有往来。美国众议院三个委员会已要求黄仁勋就与 Alice Huang 的\"往来\"出席闭门简报。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T23:00:44.000Z","url":"https://www.theverge.com/tech/1029338/nvidia-ceo-jensen-huang-china-spy"},{"id":"x2n2tnltnra9x7f2mv3hqvvf9","title":"美国国会要求 NVIDIA CEO 黄仁勋就其与中国情报关联人员接触作闭门简报","summary":"美国国会三个委员会的主席致函 NVIDIA CEO 黄仁勋，要求就其与新加坡数据中心公司 Megaspeed 高管 Alice Huang 的接触作闭门简报，此前的报道称美国情报机构认定她向北京传递信息。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T18:46:47.000Z","url":"https://x.com/rohanpaul_ai/status/2118777130150736234"},{"id":"xx66w8241whskcu890akuofxz","title":"纽约时报报道：特朗普忽视有关中国安插人员接近 Nvidia CEO 黄仁勋的情报","summary":"《纽约时报》援引匿名情报消息源报道称，约一年前特朗普获知北京通过一名与 Nvidia CEO 黄仁勋有直接接触的人获取报告，但未采取行动，部分原因是为保护 Nvidia 股价并因其与黄仁勋关系密切。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T18:29:12.000Z","url":"https://arstechnica.com/tech-policy/2026/10/report-trump-did-nothing-with-intel-that-china-planted-spy-close-to-nvidia-ceo/"},{"id":"dfsnx8zlumid0kjtackixie6r","title":"美方调查指向新加坡云厂商高管与 Nvidia CEO 的接触","summary":"纽约时报援引匿名信源称，美国情报机构约一年来监控新加坡 AI 云公司 Megaspeed 高管 Alice Huang，担心她通过与 Nvidia CEO 黄仁勋的密切接触收集 Nvidia 计划及游说特朗普政府放宽对华芯片出口的信息。Nvidia 回应称双方只是普通客户往来，云客户只获得普通商业信息，不涉及国家安全相关信息；此前商务部曾调查 Megaspeed 涉嫌向中国转售受限芯片。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T16:42:32.000Z","url":"https://techcrunch.com/2026/10/29/u-s-investigated-chinese-spy-plot-aimed-at-nvidia-ceo/"},{"id":"i6t8hf6do6sbp0vegreqjkg89","title":"Nvidia 否认美情报机构监控黄仁勋身边人士","summary":"Nvidia 否认了有关美国情报机构监控其 CEO 黄仁勋身边人士的报道。报道聚焦新加坡云服务商 Megaspeed 的 Alice Huang，官员据称怀疑其向北京传递信息。Nvidia 称 Megaspeed 是其区域云客户之一，Huang 与公司官员的接触属例行往来，并称关于 Megaspeed 将 AI 芯片转运至中国的指控“去年已被彻底调查并证伪”，公司也未收到华盛顿方面的任何预警。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T16:20:13.000Z","url":"https://x.com/rohanpaul_ai/status/2115841142294245397"},{"id":"lq97h52ctxw2nkri4qqxj5lbx","title":"纽约时报称中国情报人员瞄准英伟达 CEO 黄仁勋","summary":"据《纽约时报》报道，美国情报机构认为英伟达 CEO 黄仁勋身边一名高管为中国提供情报，此人是新加坡数据中心运营商 Megaspeed 的 Alice Huang（黄乐）。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:42:38.000Z","url":"https://the-decoder.com/chinese-spies-targeted-nvidia-ceo-jensen-huang-according-to-the-new-york-times/"}]}}};
